# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer, "stale_generation refusal records" do
  it "records one stale_generation refusal for the batch's company with no handoff step, and none for an accepted batch" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    # The suite starts at generation 1, and the contract refuses a generation
    # below 1 as invalid_snapshot, so raise it before building a stale batch.
    TimekeepingOwnership.current.update!(generation: 2)
    current = TimekeepingOwnership.current.generation
    expect(TimekeepingOwnership.current.handoff_step).to be_nil

    item = lambda do |id, generation, position|
      entry = TimekeepingSnapshots.entry(id:, company_id: company.id, version: 1, project_id: project.id, user_id: user.id)
      TimekeepingSnapshots.item(entry, generation:, outbox_position: position)
    end

    accepted = described_class.call(batch: TimekeepingSnapshots.batch(item.call(92_101, current, 1)),
                                    idempotency_key: SecureRandom.uuid)
    expect(accepted.status).to eq(200)
    expect(TimekeepingStaleGenerationRefusal.count).to eq(0)

    # "any `409 stale_generation` outside a handoff;"
    # Two snapshots of one company in one refused batch leave exactly one row for that company.
    stale = TimekeepingSnapshots.batch(item.call(92_102, current - 1, 2), item.call(92_103, current - 1, 3))
    result = described_class.call(batch: stale, idempotency_key: SecureRandom.uuid)

    expect([result.status, result.body.to_h.stringify_keys]).to eq([409, { "reason" => "stale_generation" }])
    expect(TimekeepingStaleGenerationRefusal.pluck(:company_id, :handoff_step)).to eq([[company.id, nil]])
    expect(TimekeepingStaleGenerationRefusal.first.created_at).to be_within(1.minute).of(Time.current)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer, "stale_generation refusal records during a handoff" do
  it "records the handoff step in progress when a stale_generation refusal happens during a handoff" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    ownership = TimekeepingOwnership.current
    # Generation 2, so the previous generation is 1, which the contract accepts as valid.
    ownership.update_columns(generation: 2, handoff_step: "close_admission")
    expect(TimekeepingOwnership.current.handoff_step).to eq("close_admission")

    entry = TimekeepingSnapshots.entry(id: 92_201, company_id: company.id, version: 1, project_id: project.id,
                                       user_id: create(:user).id)
    batch = TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: ownership.generation - 1,
                                                                        outbox_position: 1))

    result = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    # The alert fires only "outside a handoff", so the row must say a handoff was under way.
    expect(result.status).to eq(409)
    expect(TimekeepingStaleGenerationRefusal.pluck(:company_id, :handoff_step)).to eq([[company.id, "close_admission"]])
  end
end
